function renderAdminEmployees(){const all=[...(adminData.empleados||[])].sort((a,b)=>employeeSortKey(a).localeCompare(employeeSortKey(b),'es')),departments=[...new Set(all.map(e=>e.departamento).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),branches=[...new Set(all.map(e=>e.sucursal).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),terms=filterText(employeeFilters.search).split(/\s+/).filter(Boolean),employeeSearchText=e=>filterText([e.nombres,e.apellido_paterno,e.apellido_materno,e.numero_empleado,e.correo,e.telefono,e.departamento,e.sucursal,e.region,e.puesto,e.profesion,e.perfil].join(' ')),rows=all.filter(e=>{const haystack=employeeSearchText(e);return(!terms.length||terms.every(term=>haystack.includes(term)))&&(!employeeFilters.department||e.departamento===employeeFilters.department)&&(!employeeFilters.branch||e.sucursal===employeeFilters.branch)&&(!employeeFilters.status||e.estado===employeeFilters.status)});$('#adminEmployees').innerHTML=`<div class="admin-list-header"><div><h3>Plantilla de empleados</h3><p>Ordenada alfabéticamente por apellido · Mostrando ${rows.length} de ${all.length} empleados</p></div></div><div class="employee-filters" aria-label="Filtros de empleados"><label class="employee-search"><span>Buscar empleado</span><input data-employee-filter="search" type="search" value="${safe(employeeFilters.search)}" placeholder="Nombre, apellido, correo, puesto o perfil"></label><label><span>Departamento</span><select data-employee-filter="department"><option value="">Todos</option>${departments.map(x=>adminOption(x,x,employeeFilters.department)).join('')}</select></label><label><span>Sucursal</span><select data-employee-filter="branch"><option value="">Todas</option>${branches.map(x=>adminOption(x,x,employeeFilters.branch)).join('')}</select></label><label><span>Estado</span><select data-employee-filter="status">${adminOption('','Todos',employeeFilters.status)}${adminOption('ACTIVO','Activo',employeeFilters.status)}${adminOption('SUSPENDIDO_TEMPORAL','Suspensión temporal',employeeFilters.status)}${adminOption('TERMINADO','Terminado',employeeFilters.status)}</select></label><button class="clear-employee-filters" data-clear-employee-filters ${Object.values(employeeFilters).some(Boolean)?'':'disabled'}>Limpiar filtros</button></div><div class="admin-table"><div class="admin-row head"><div>Nombre(s) y apellidos</div><div>Área laboral</div><div>Ubicación</div><div>Perfil de seguridad</div><div>Acción</div></div>${rows.length?rows.map(e=>`<div class="admin-row" data-employee-search="${safe(employeeSearchText(e))}"><div>${employeeNameMarkup(e)}<small>${safe(e.numero_empleado)} · ${safe(e.correo||'Correo pendiente')} · ${safe(e.telefono||'Teléfono pendiente')}</small></div><div><strong>${safe(e.departamento||'Sin departamento')} · ${safe(e.puesto||'Sin puesto')}</strong><small>Profesión: ${safe(e.profesion||'Pendiente')} · ${safe(adminDate(e.fecha_ingreso))}</small></div><div><strong>${safe(e.region||'Región MTY')}</strong><small>Sucursal ${safe(e.sucursal||'pendiente')} · ${employeeStatus(e.estado)}</small></div><div><strong>${safe(e.perfil||'Sin asignar')}</strong><small>Matriz de Seguridad</small></div><div><button class="edit-admin" data-edit-employee="${safe(e.id)}">Editar</button></div></div>`).join(''):'<div class="admin-empty">No hay empleados que coincidan con estos filtros.</div>'}</div>`}
function employeeSearchValue(employee){return filterText([employee.numero_empleado,employee.nombres,employee.apellido_paterno,employee.apellido_materno,employee.correo,employee.telefono,employee.departamento,employee.puesto,employee.sucursal,employee.region,employee.sede,employee.profesion,employee.perfil].join(' '))}
