function renderSystemNotifications(){const profiles=adminData.perfiles||[],pending=(adminData.empleados||[]).filter(e=>!e.perfil&&!e.perfil_id).map(e=>({employee:e,suggestion:inferredEmployeeProfile(e).profile||''}));$('#adminProfiles').insertAdjacentHTML('beforeend',`<section class="systems-notifications shortcuts-requests"><div class="config-heading"><div><h3>Solicitudes para actualizar Shortcuts</h3><p>Capital Humano proporciona los datos laborales; aquí se propone y confirma el perfil del sistema externo Shortcuts.</p></div><span class="status-pill">${pending.length} pendientes</span></div><div class="systems-notification-list">${pending.length?pending.map(({employee:e,suggestion})=>{const suggested=profiles.find(p=>filterText(p.nombre)===filterText(suggestion))?.id||'';return `<article class="systems-notification"><div>${employeeNameMarkup(e)}<small>${safe(e.numero_empleado||'Clave pendiente')} · ${safe(e.departamento||'Sin departamento')} · ${safe(e.puesto||'Sin puesto')} · ${safe(e.sucursal||'Sin sucursal')}</small></div><label><span>Perfil de Shortcuts sugerido: ${safe(suggestion||'Revisión manual')}</span><select data-security-select="${safe(e.id)}"><option value="">Seleccionar perfil de Shortcuts</option>${profiles.map(p=>adminOption(p.id,p.nombre,suggested)).join('')}</select></label><button class="assign-security" data-assign-security="${safe(e.id)}">Confirmar perfil</button></article>`}).join(''):'<div class="systems-empty">No hay solicitudes pendientes de asignación en Shortcuts.</div>'}</div></section>`)}
