async function loadNexusAccess(force=false){if(nexusAccessLoaded&&!force){renderNexusAccess();return}$('#nexusAccessStatus').textContent='Cargando políticas desde la nube…';const {data,error}=await appCore.access.load();if(error){$('#nexusAccessStatus').textContent='No tienes permiso para consultar o administrar esta matriz.';return}nexusAccessData=data||nexusAccessData;nexusAccessLoaded=true;renderNexusAccess()}
function updateNexusDecisionState(command){const row=nexusAccessData.decisiones.find(x=>x.perfil_id===command.p_perfil_id&&x.politica_id===command.p_politica_id);if(row)row.decision=command.p_decision;else nexusAccessData.decisiones.push({perfil_id:command.p_perfil_id,politica_id:command.p_politica_id,decision:command.p_decision})}
$('#nexusAccessGrid').onclick=async e=>{const button=e.target.closest('[data-nexus-decision]');if(!button)return;button.disabled=true;const command={p_perfil_id:button.dataset.nexusProfile,p_politica_id:button.dataset.nexusPolicy,p_decision:button.dataset.nexusDecision},{error}=await appCore.access.saveDecision(command);if(error){button.disabled=false;toast('No se pudo modificar: '+error.message);return}updateNexusDecisionState(command);if(button.dataset.nexusScreen&&command.p_decision==='DENEGAR'){const childPolicies=(nexusAccessData.politicas||[]).filter(policy=>policy.modulo===button.dataset.nexusScreen&&policy.id!==command.p_politica_id);for(const policy of childPolicies){const childCommand={p_perfil_id:command.p_perfil_id,p_politica_id:policy.id,p_decision:'DENEGAR'},result=await appCore.access.saveDecision(childCommand);if(!result.error)updateNexusDecisionState(childCommand)}}renderNexusAccess();toast(button.dataset.nexusScreen&&command.p_decision==='DENEGAR'?'Pantalla y funciones bloqueadas':'Política guardada en la nube')};
$('#newNexusProfile').onclick=()=>{$('#nexusProfileForm').reset();$('#nexusProfileDialog').showModal()};$('#closeNexusProfile').onclick=$('#cancelNexusProfile').onclick=()=>$('#nexusProfileDialog').close();
$('#nexusProfileForm').onsubmit=async e=>{e.preventDefault();const button=$('#saveNexusProfile');button.disabled=true;button.textContent='Creando…';const command={p_codigo:$('#nexusProfileCode').value.trim(),p_nombre:$('#nexusProfileName').value.trim(),p_descripcion:$('#nexusProfileDescription').value.trim()||null},{error}=await appCore.access.saveProfile(command);button.disabled=false;button.textContent='Crear perfil';if(error){toast('No se pudo crear: '+error.message);return}$('#nexusProfileDialog').close();nexusAccessLoaded=false;await loadNexusAccess(true);toast('Perfil creado con todo en Sin acceso')};
function showNexusPanel(panel){const users=panel==='users';$('#nexusProfilesPanel').hidden=users;$('#nexusUsersPanel').hidden=!users;$('.nexus-access-scroll').hidden=users;document.querySelectorAll('[data-nexus-panel]').forEach(button=>button.classList.toggle('active',button.dataset.nexusPanel===panel));$('#nexusAccessStatus').hidden=users}
document.querySelector('.nexus-panel-tabs').onclick=e=>{const button=e.target.closest('[data-nexus-panel]');if(button)showNexusPanel(button.dataset.nexusPanel)};
function renderNexusEmployeeOptions(){const terms=filterText($('#nexusUserEmployeeSearch').value).split(/\s+/).filter(Boolean),all=[...(adminData.empleados||[])].sort((a,b)=>employeeSortKey(a).localeCompare(employeeSortKey(b),'es')),matches=all.filter(employee=>{const name=`${employee.nombres||''} ${employee.apellido_paterno||''} ${employee.apellido_materno||''}`,haystack=filterText([employee.numero_empleado,name,employee.departamento,employee.puesto,employee.sucursal,employee.region,employee.sede,employee.correo].join(' '));return !terms.length||terms.every(term=>haystack.includes(term))}),shown=matches.slice(0,60);$('#nexusUserEmployee').innerHTML='<option value="">Sin vincular a empleado</option>'+shown.map(employee=>{const name=`${employee.nombres||''} ${employee.apellido_paterno||''} ${employee.apellido_materno||''}`.trim(),location=employee.sucursal||employee.sede||employee.region||'Sin sede';return `<option value="${safe(employee.id)}" data-email="${safe(employee.correo||'')}">${safe(employee.numero_empleado||'Sin ID')} · ${safe(name)} · ${safe(employee.departamento||'Sin área')} · ${safe(location)}</option>`}).join('');$('#nexusEmployeeSearchCount').textContent=terms.length?`${matches.length} empleado${matches.length===1?'':'s'} encontrado${matches.length===1?'':'s'}`:`${all.length} empleados disponibles · escribe para reducir la lista`}
function renderNexusEmployeeOptions(){
  const query=$('#nexusUserEmployeeSearch').value;
  const all=[...(adminData.empleados||[])].sort((a,b)=>employeeSortKey(a).localeCompare(employeeSortKey(b),'es'));
  const matches=all.filter(employee=>employeeMatches(employee,query));
  const shown=query.trim()?matches:matches.slice(0,60);
  $('#nexusUserEmployee').innerHTML='<option value="">Sin vincular a empleado</option>'+shown.map(employee=>{const name=`${employee.nombres||''} ${employee.apellido_paterno||''} ${employee.apellido_materno||''}`.trim(),location=employee.sucursal||employee.sede||employee.region||'Sin sede';return `<option value="${safe(employee.id)}" data-email="${safe(employee.correo||'')}">${safe(employee.numero_empleado||'Sin ID')} · ${safe(name)} · ${safe(employee.departamento||'Sin área')} · ${safe(location)}</option>`}).join('');
  $('#nexusEmployeeSearchCount').textContent=query.trim()?`${matches.length} de ${all.length} empleados encontrados`:`${all.length} empleados disponibles · escribe nombre o número`;
}
$('#newNexusUser').onclick=async()=>{if(!adminLoaded)await loadAdmin();$('#nexusUserForm').reset();renderNexusEmployeeOptions();$('#nexusUserProfile').innerHTML='<option value="">Seleccionar nivel…</option>'+(nexusAccessData.perfiles||[]).map(profile=>`<option value="${safe(profile.id)}">${safe(profile.nombre)}</option>`).join('');$('#nexusUserDialog').showModal();setTimeout(()=>$('#nexusUserEmployeeSearch').focus(),80)};
function selectSingleNexusEmployee(){const select=$('#nexusUserEmployee');if(select.options.length!==2)return;select.selectedIndex=1;const option=select.selectedOptions[0],email=option?.dataset.email;if(email)$('#nexusUserEmail').value=email;$('#nexusEmployeeSearchCount').textContent+=' · empleado seleccionado'}
$('#nexusUserEmployeeSearch').oninput=()=>{renderNexusEmployeeOptions();selectSingleNexusEmployee()};
$('#nexusUserEmployee').onchange=e=>{const option=e.target.selectedOptions[0],email=option?.dataset.email;if(email)$('#nexusUserEmail').value=email};
['nexusUserPin','nexusUserPinConfirm'].forEach(id=>{$(`#${id}`).oninput=e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,4)}});
$('#closeNexusUser').onclick=$('#cancelNexusUser').onclick=()=>$('#nexusUserDialog').close();
$('#nexusUserForm').onsubmit=async e=>{e.preventDefault();const pin=$('#nexusUserPin').value,pinConfirm=$('#nexusUserPinConfirm').value;if(!/^\d{4}$/.test(pin)){toast('El PIN debe contener exactamente 4 números');return}if(pin!==pinConfirm){toast('Los dos PIN no coinciden');return}const button=$('#saveNexusUser'),employeeLabel=$('#nexusUserEmployee').selectedOptions[0]?.textContent?.trim()||'Usuario',profileLabel=$('#nexusUserProfile').selectedOptions[0]?.textContent?.trim()||'nivel seleccionado';button.disabled=true;button.textContent='Guardando…';const command={p_correo:$('#nexusUserEmail').value.trim().toLowerCase(),p_empleado_id:$('#nexusUserEmployee').value||null,p_perfil_id:$('#nexusUserProfile').value,p_alcance_tipo:$('#nexusUserScope').value,p_pin:pin},{error}=await appCore.access.saveUser(command);button.disabled=false;button.textContent='Guardar usuario';if(error){toast('No se pudo dar de alta: '+error.message);return}$('#nexusUserDialog').close();nexusAccessLoaded=false;await loadNexusAccess(true);showNexusPanel('users');$('#nexusUserSuccessMessage').textContent=`${employeeLabel} fue dado de alta con el nivel ${profileLabel}.`;$('#nexusUserSuccessDialog').showModal();toast('Alta correcta: usuario, nivel de seguridad y PIN guardados')};
